INSERT INTO public._ex_import_src (name, old_names, existing, equipment, muscles, level, easier, harder, description, tags, measure) VALUES
  ('קימה מכיסא', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן'], 1, NULL, 'סקוואט לכיסא', 'יושבים על כיסא, רגליים ברוחב כתפיים. קמים בלי עזרת הידיים ומתיישבים לאט.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('סקוואט לכיסא', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן'], 1, 'קימה מכיסא', 'סקוואט', 'יורדים לאט עד שהישבן נוגע בכיסא, בלי להתיישב, וקמים. גב ישר.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('סקוואט', '{}'::text[], true, 'bodyweight', ARRAY['רגליים', 'ישבן'], 2, 'סקוואט לכיסא', 'סקוואט עם עצירה', 'רגליים ברוחב כתפיים. יורדים עם הישבן אחורה כאילו מתיישבים, גב ישר ועקבים על הרצפה, וקמים.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('סקוואט רחב', '{}'::text[], true, 'bodyweight', ARRAY['ירך פנימית', 'ישבן'], 2, 'סקוואט לכיסא', 'סקוואט עם עצירה', 'רגליים רחבות, אצבעות פונות החוצה. יורדים ישר למטה, ברכיים בכיוון האצבעות.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('סקוואט עם עצירה', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן'], 3, 'סקוואט', 'סקוואט בולגרי', 'סקוואט רגיל, עוצרים 3 שניות בנקודה הנמוכה וקמים.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('סקוואט קפיצה', '{}'::text[], true, 'bodyweight', ARRAY['רגליים', 'דופק'], 4, 'סקוואט', NULL, 'יורדים לסקוואט וקופצים למעלה בכוח. נוחתים רך וישר לסקוואט הבא.', '{}'::text[], 'reps'),
  ('פיסטול לספסל', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן'], 4, 'סקוואט בולגרי', 'פיסטול', 'עומדים על רגל אחת מול ספסל, יורדים לאט עד שהישבן נוגע בו וקמים על אותה רגל.', '{}'::text[], 'reps'),
  ('פיסטול', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן', 'שיווי משקל'], 5, 'פיסטול לספסל', NULL, 'סקוואט על רגל אחת עד הסוף, הרגל השנייה ישרה קדימה. קמים בלי עזרה.', '{}'::text[], 'reps'),
  ('ישיבה על קיר', '{}'::text[], false, 'bodyweight', ARRAY['ארבע ראשי'], 2, NULL, 'סקוואט עם עצירה', 'גב צמוד לקיר, יורדים עד שהברכיים ב-90 מעלות ומחזיקים.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'time'),
  ('לאנג'' סטטי עם תמיכה', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן'], 1, NULL, 'לאנג'' לאחור', 'עומדים בפיסוק קדימה-אחורה, יד על קיר. יורדים ועולים במקום בלי להזיז רגליים.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('לאנג'' לאחור', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן'], 2, 'לאנג'' סטטי עם תמיכה', 'לאנג''ים', 'צעד גדול אחורה, יורדים עד שהברך האחורית כמעט ברצפה וחוזרים לעמידה.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('לאנג''ים', ARRAY['לאנצ׳ים', 'לאנצ''ים'], true, 'bodyweight', ARRAY['רגליים', 'ישבן'], 2, 'לאנג'' לאחור', 'לאנג'' בהליכה', 'צעד גדול קדימה, יורדים עד שהברך האחורית כמעט ברצפה. דוחפים מהעקב הקדמי וחוזרים.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('לאנג'' צידי', ARRAY['לאנצ׳י צידי', 'לאנצ''י צידי'], true, 'bodyweight', ARRAY['ירך פנימית', 'ישבן'], 2, 'לאנג'' סטטי עם תמיכה', 'לאנג'' בהליכה', 'צעד רחב לצד, יורדים על הרגל הזו עם ישבן אחורה, השנייה ישרה. חוזרים למרכז.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('לאנג'' בהליכה', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן'], 3, 'לאנג''ים', 'לאנג'' בקפיצה', 'לאנג'' קדימה, ובמקום לחזור מתקדמים עם הרגל האחורית ללאנג'' הבא.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('לאנג'' בקפיצה', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'דופק'], 4, 'לאנג'' בהליכה', NULL, 'מלאנג'', קופצים ומחליפים רגליים באוויר, נוחתים ישר ללאנג'' הבא.', '{}'::text[], 'reps'),
  ('הרמות עקבים', ARRAY['הרמות עקביים'], true, 'bodyweight', ARRAY['שוקיים'], 1, NULL, 'הרמות עקבים רגל אחת', 'עומדים זקוף, עולים על קצות האצבעות, עוצרים שנייה ויורדים לאט. אפשר יד על קיר.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('הרמות עקבים רגל אחת', '{}'::text[], false, 'bodyweight', ARRAY['שוקיים'], 2, 'הרמות עקבים', 'הרמות עקבים על מדרגה', 'כמו הרמות עקבים, על רגל אחת, יד על קיר לשיווי משקל.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('הרמות עקבים על מדרגה', '{}'::text[], false, 'bodyweight', ARRAY['שוקיים'], 3, 'הרמות עקבים רגל אחת', NULL, 'קדמת כף הרגל על מדרגה, עקבים באוויר. יורדים עד מתיחה ועולים עד הסוף.', ARRAY['no_jumps', 'no_floor'], 'reps'),
  ('עלייה על מדרגה', '{}'::text[], false, 'bodyweight', ARRAY['רגליים', 'ישבן'], 1, NULL, 'עליות על ספסל', 'עולים על מדרגה נמוכה עם רגל אחת, מצרפים את השנייה ויורדים. מחליפים רגל מובילה.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('הליכה במקום', '{}'::text[], false, 'bodyweight', ARRAY['דופק'], 1, NULL, 'צעדי כוכב', 'הולכים במקום ומרימים ברכיים, ידיים זזות כמו בהליכה.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'time'),
  ('צעדי כוכב', '{}'::text[], false, 'bodyweight', ARRAY['דופק'], 1, 'הליכה במקום', 'קפיצות כוכב', 'צעד לצד עם רגל אחת ופותחים ידיים מעל הראש, חוזרים ומחליפים צד. בלי קפיצה.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'time'),
  ('קפיצות כוכב', '{}'::text[], true, 'bodyweight', ARRAY['דופק'], 2, 'צעדי כוכב', NULL, 'קופצים ופותחים ידיים ורגליים לצדדים, קופצים וסוגרים.', '{}'::text[], 'time'),
  ('הרמת רגל לצד בעמידה', '{}'::text[], false, 'bodyweight', ARRAY['ישבן צידי'], 1, NULL, 'לאנג'' צידי', 'יד על קיר, מרימים רגל ישרה לצד בלי להטות את הגוף ויורדים לאט.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('כפיפות בטן בעמידה', '{}'::text[], false, 'bodyweight', ARRAY['בטן'], 1, NULL, 'דד באג', 'עומדים, ידיים מאחורי הראש. מרימים ברך ומקרבים אליה את המרפק הנגדי, לסירוגין.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('הרמות ברכיים בישיבה', '{}'::text[], false, 'bodyweight', ARRAY['בטן תחתונה'], 1, NULL, 'כפיפות בטן בעמידה', 'יושבים על קצה כיסא, ידיים על הצדדים. מרימים ברכיים לחזה ומורידים לאט.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('אגרופים בישיבה', '{}'::text[], false, 'bodyweight', ARRAY['כתפיים', 'דופק'], 1, NULL, 'הליכה במקום', 'יושבים זקוף ומכים אגרופים באוויר קדימה ולמעלה בקצב קבוע.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'time'),
  ('שכיבות סמיכה על קיר', '{}'::text[], false, 'bodyweight', ARRAY['חזה', 'יד אחורית'], 1, NULL, 'שכיבות סמיכה על שולחן', 'ידיים על קיר בגובה הכתפיים, צעד אחורה. מקרבים חזה לקיר ודוחפים.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('שכיבות סמיכה על שולחן', '{}'::text[], false, 'bodyweight', ARRAY['חזה', 'יד אחורית'], 1, 'שכיבות סמיכה על קיר', 'שכיבות סמיכה שיפוע חיובי', 'ידיים על שולחן יציב או שיש, גוף ישר. מקרבים חזה לשולחן ודוחפים.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'reps'),
  ('שכיבות סמיכה על הברכיים', '{}'::text[], false, 'bodyweight', ARRAY['חזה', 'יד אחורית'], 2, 'שכיבות סמיכה שיפוע חיובי', 'שכיבות סמיכה', 'כמו שכיבת סמיכה, הברכיים על הרצפה. גוף ישר מהראש לברכיים.', '{}'::text[], 'reps'),
  ('שכיבות סמיכה', '{}'::text[], true, 'bodyweight', ARRAY['חזה', 'יד אחורית', 'כתפיים'], 3, 'שכיבות סמיכה על הברכיים', 'שכיבות סמיכה צרות', 'ידיים מעט רחבות מהכתפיים, גוף ישר. יורדים עד שהחזה קרוב לרצפה ודוחפים.', '{}'::text[], 'reps'),
  ('שכיבות סמיכה רחבות', '{}'::text[], true, 'bodyweight', ARRAY['חזה'], 3, 'שכיבות סמיכה', 'שכיבות סמיכה שיפוע שלילי', 'ידיים רחבות הרבה מהכתפיים. יורדים עם החזה בין הידיים.', '{}'::text[], 'reps'),
  ('שכיבות סמיכה צרות', '{}'::text[], true, 'bodyweight', ARRAY['יד אחורית', 'חזה'], 4, 'שכיבות סמיכה', 'שכיבות סמיכה יהלום', 'ידיים ברוחב כתפיים, מרפקים צמודים לגוף בירידה.', '{}'::text[], 'reps'),
  ('שכיבות סמיכה יהלום', '{}'::text[], true, 'bodyweight', ARRAY['יד אחורית'], 4, 'שכיבות סמיכה צרות', 'שכיבות סמיכה ארצ''ר', 'אגודלים ואצבעות מורות יוצרים יהלום מתחת לחזה. יורדים עם מרפקים צמודים.', '{}'::text[], 'reps'),
  ('שכיבות סמיכה ארצ''ר', '{}'::text[], false, 'bodyweight', ARRAY['חזה', 'יד אחורית'], 5, 'שכיבות סמיכה שיפוע שלילי', NULL, 'ידיים רחבות מאוד. יורדים לצד אחד, היד השנייה נשארת ישרה. מחליפים צד.', '{}'::text[], 'reps'),
  ('שכיבות סמיכה פליאומטריות', '{}'::text[], false, 'bodyweight', ARRAY['חזה', 'כוח מתפרץ'], 5, 'שכיבות סמיכה', NULL, 'דוחפים בכוח עד שהידיים עוזבות את הרצפה, נוחתים רך וממשיכים.', '{}'::text[], 'reps'),
  ('פייק פוש-אפ', '{}'::text[], false, 'bodyweight', ARRAY['כתפיים'], 3, 'שכיבות סמיכה', NULL, 'ישבן גבוה, גוף בצורת V הפוכה. מורידים את הראש לרצפה בין הידיים ודוחפים.', '{}'::text[], 'reps'),
  ('סמוך קום בלי קפיצה', '{}'::text[], false, 'bodyweight', ARRAY['כל הגוף', 'דופק'], 2, NULL, 'סמוך קום', 'ידיים לרצפה, צעד אחורה עם כל רגל לפלאנק, צעד קדימה וקמים. בלי קפיצות.', ARRAY['no_jumps'], 'reps'),
  ('סמוך קום', '{}'::text[], true, 'bodyweight', ARRAY['כל הגוף', 'דופק'], 4, 'סמוך קום בלי קפיצה', NULL, 'יורדים לסקוואט, ידיים לרצפה, קופצים לשכיבת סמיכה, חוזרים לסקוואט וקופצים למעלה.', '{}'::text[], 'reps'),
  ('מטפס הרים על ספסל', '{}'::text[], false, 'bodyweight', ARRAY['בטן', 'דופק'], 2, NULL, 'מטפס הרים', 'ידיים על ספסל או כיסא יציב, גוף ישר. מקרבים ברכיים לחזה לסירוגין, בקצב נוח.', ARRAY['no_jumps'], 'reps'),
  ('מטפס הרים', '{}'::text[], true, 'bodyweight', ARRAY['בטן', 'כתפיים', 'דופק'], 3, 'מטפס הרים על ספסל', NULL, 'מנח שכיבת סמיכה, מקרבים ברכיים לחזה לסירוגין בקצב מהיר. גב ישר.', '{}'::text[], 'time'),
  ('פלאנק על קיר', '{}'::text[], false, 'bodyweight', ARRAY['בטן'], 1, NULL, 'פלאנק על הברכיים', 'אמות על קיר, צעד אחורה עד שהגוף נטוי וישר. מכווצים בטן ומחזיקים.', ARRAY['struggling', 'no_jumps', 'no_floor'], 'time'),
  ('פלאנק על הברכיים', '{}'::text[], false, 'bodyweight', ARRAY['בטן'], 2, 'פלאנק על קיר', 'פלאנק', 'אמות וברכיים על הרצפה, גוף ישר מהראש לברכיים. מחזיקים.', '{}'::text[], 'time'),
  ('פלאנק', '{}'::text[], true, 'bodyweight', ARRAY['בטן', 'גוף מרכזי'], 3, 'פלאנק על הברכיים', 'פלאנק צידי', 'אמות וקצות אצבעות, גוף בקו ישר. בלי ישבן למעלה ובלי גב שוקע.', '{}'::text[], 'time'),
  ('פלאנק צידי', '{}'::text[], false, 'bodyweight', ARRAY['בטן צידית'], 3, 'פלאנק', 'פלאנק עם מגע בכתף', 'שוכבים על הצד, נשענים על אמה אחת, מרימים אגן עד קו ישר ומחזיקים. אפשר על הברכיים.', '{}'::text[], 'time'),
  ('פלאנק עם מגע בכתף', '{}'::text[], false, 'bodyweight', ARRAY['בטן', 'כתפיים'], 4, 'פלאנק צידי', NULL, 'מנח שכיבת סמיכה, נוגעים ביד בכתף הנגדית לסירוגין בלי שהאגן יזוז.', '{}'::text[], 'reps'),
  ('דד באג', '{}'::text[], false, 'bodyweight', ARRAY['בטן עמוקה'], 1, 'כפיפות בטן בעמידה', 'כפיפות בטן', 'שוכבים על הגב, ידיים למעלה וברכיים ב-90. מורידים יד ורגל נגדיות לאט, גב תחתון צמוד לרצפה.', '{}'::text[], 'reps'),
  ('כפיפות בטן', '{}'::text[], true, 'bodyweight', ARRAY['בטן'], 2, 'דד באג', 'החזקת הולו', 'שוכבים על הגב, ברכיים כפופות. מרימים כתפיים מהרצפה בעזרת הבטן, בלי למשוך את הצוואר.', '{}'::text[], 'reps'),
  ('אופניים', '{}'::text[], true, 'bodyweight', ARRAY['בטן', 'בטן צידית'], 2, 'כפיפות בטן', 'החזקת הולו', 'שוכבים על הגב, ידיים מאחורי הראש. מקרבים מרפק לברך הנגדית לסירוגין, כמו דיווש.', '{}'::text[], 'reps'),
  ('כפיפות בטן רגל רגל', ARRAY['כפיבות בטן רגל רגל'], true, 'bodyweight', ARRAY['בטן תחתונה'], 2, 'כפיפות בטן', 'הרמות ברכיים בתלייה', 'שוכבים על הגב, רגליים ישרות מעט מעל הרצפה. מרימים ומורידים רגל אחרי רגל בלי לגעת ברצפה.', '{}'::text[], 'reps'),
  ('פינגווינים', '{}'::text[], true, 'bodyweight', ARRAY['בטן צידית'], 2, NULL, 'פלאנק צידי', 'שוכבים על הגב, ברכיים כפופות, כתפיים מעט מורמות. נוגעים ביד בעקב, צד אחרי צד.', '{}'::text[], 'reps'),
  ('רוסיאן טוויסט', '{}'::text[], false, 'bodyweight', ARRAY['בטן צידית'], 3, 'פינגווינים', NULL, 'יושבים נטויים לאחור, רגליים מורמות או על הרצפה. מסובבים את הגוף מצד לצד.', '{}'::text[], 'reps'),
  ('החזקת הולו', '{}'::text[], false, 'bodyweight', ARRAY['בטן'], 3, 'כפיפות בטן', 'V-אפ', 'שוכבים על הגב, מרימים כתפיים ורגליים ישרות מהרצפה, גב תחתון צמוד. מחזיקים.', '{}'::text[], 'time'),
  ('V-אפ', '{}'::text[], false, 'bodyweight', ARRAY['בטן'], 4, 'החזקת הולו', NULL, 'מהשכיבה, מרימים יחד גוף ורגליים ישרות ונוגעים בכפות הרגליים.', '{}'::text[], 'reps'),
