-- =============================================================================
-- Exercise library v2 (supabase/data/exercises-2026-11.csv): 180 exercises,
-- 71 existing (9 renamed in place) and 109 new, with a level (1–5), an easier and
-- a harder version, tags, and reps / time.
--
--   * Existing exercises are updated in place (same id), so every workout that
--     already uses them keeps working. Nothing is deleted.
--   * Renamed: the 6 marked "תיקון שם", plus 3 marked "קיים" whose name in the
--     database is spelled differently (לאנצ׳ים, לאנצ׳י צידי, הרמות עקביים).
--   * The 4 pull-up progressions of 3.11 (not in the file) get a level and join as a
--     side path into "מתח" (section 6b). Left as they are: the two "Running" test rows.
--   * New exercises have no video (media_url NULL): the app shows the text.
--   * muscles → the existing muscle_groups column (no second column).
--   * equipment: the existing codes, plus 'band' (גומייה) and 'mobility' (גמישות).
--     The few rows saved in Hebrew / misspelled are normalised.
--   * tags: 'struggling' (מתקשים), 'no_jumps' (בלי קפיצות), 'no_floor' (בלי רצפה).
--   * measure: 'reps' / 'time'. A plan's own is_duration still decides per plan.
--   * difficulty (beginner / intermediate / advanced) follows the level: 1–2 / 3 / 4–5.
--
--   * exercise_swaps: every "too easy / too hard" swap, for the admin.
--
-- One transaction: all or nothing. Safe to run again (it converges to the file).
-- Run after a backup (scripts/backup-db.ps1). The checks at the end should be empty.
-- =============================================================================

BEGIN;

-- ── 1. New columns ───────────────────────────────────────────────────────────
ALTER TABLE public.exercises
  ADD COLUMN IF NOT EXISTS level      SMALLINT,
  ADD COLUMN IF NOT EXISTS easier_id  UUID REFERENCES public.exercises(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS harder_id  UUID REFERENCES public.exercises(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS tags       TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS measure    TEXT NOT NULL DEFAULT 'reps';

ALTER TABLE public.exercises DROP CONSTRAINT IF EXISTS exercises_level_check;
ALTER TABLE public.exercises ADD CONSTRAINT exercises_level_check CHECK (level IS NULL OR level BETWEEN 1 AND 5);
ALTER TABLE public.exercises DROP CONSTRAINT IF EXISTS exercises_measure_check;
ALTER TABLE public.exercises ADD CONSTRAINT exercises_measure_check CHECK (measure IN ('reps', 'time'));
ALTER TABLE public.exercises DROP CONSTRAINT IF EXISTS exercises_tags_check;
ALTER TABLE public.exercises ADD CONSTRAINT exercises_tags_check CHECK (tags <@ ARRAY['struggling', 'no_jumps', 'no_floor']::text[]);
ALTER TABLE public.exercises DROP CONSTRAINT IF EXISTS exercises_not_own_version;
ALTER TABLE public.exercises ADD CONSTRAINT exercises_not_own_version CHECK (easier_id IS DISTINCT FROM id AND harder_id IS DISTINCT FROM id);

CREATE INDEX IF NOT EXISTS exercises_level_idx ON public.exercises (level);

-- ── 2. The file ──────────────────────────────────────────────────────────────
DROP TABLE IF EXISTS public._ex_import_src;
CREATE TABLE public._ex_import_src (
  name TEXT, old_names TEXT[], existing BOOLEAN, equipment TEXT, muscles TEXT[], level SMALLINT,
  easier TEXT, harder TEXT, description TEXT, tags TEXT[], measure TEXT
);


-- ── 3. Renames (same row, same id) ───────────────────────────────────────────
UPDATE public.exercises e
SET name = s.name
FROM public._ex_import_src s
WHERE s.existing
  AND e.name = ANY (s.old_names)
  AND NOT EXISTS (SELECT 1 FROM public.exercises x WHERE x.name = s.name);

-- ── 4. Existing exercises: text, level, tags, equipment (video kept) ────────
UPDATE public.exercises e
SET description   = s.description,
    muscle_groups = s.muscles,
    equipment     = s.equipment,
    level         = s.level,
    difficulty    = CASE WHEN s.level <= 2 THEN 'beginner' WHEN s.level = 3 THEN 'intermediate' ELSE 'advanced' END,
    tags          = s.tags,
    measure       = s.measure
FROM public._ex_import_src s
WHERE s.existing AND e.name = s.name;

-- ── 5. New exercises (no video yet) ──────────────────────────────────────────
SELECT s.name, s.description, s.muscles, s.equipment,
       CASE WHEN s.level <= 2 THEN 'beginner' WHEN s.level = 3 THEN 'intermediate' ELSE 'advanced' END,
       s.level, s.tags, s.measure
FROM public._ex_import_src s
WHERE NOT s.existing
  AND NOT EXISTS (SELECT 1 FROM public.exercises x WHERE x.name = s.name);

-- ── 6. Easier / harder versions: names → ids ─────────────────────────────────
UPDATE public.exercises e
SET easier_id = (SELECT x.id FROM public.exercises x WHERE x.name = s.easier ORDER BY x.created_at LIMIT 1),
    harder_id = (SELECT x.id FROM public.exercises x WHERE x.name = s.harder ORDER BY x.created_at LIMIT 1)
FROM public._ex_import_src s
WHERE e.name = s.name;

-- ── 6b. The 4 pull-up progressions of 3.11 (not in the file): a side path into
--        "מתח", from "תלייה אקטיבית". The file's own chain is left as it is. ──
DROP TABLE IF EXISTS public._ex_import_pullup;
CREATE TABLE public._ex_import_pullup (name TEXT, level SMALLINT, measure TEXT, easier TEXT, harder TEXT);

UPDATE public.exercises e
SET level      = p.level,
    measure    = p.measure,
    equipment  = 'pull-up bar',
    difficulty = CASE WHEN p.level <= 2 THEN 'beginner' WHEN p.level = 3 THEN 'intermediate' ELSE 'advanced' END,
    easier_id  = (SELECT x.id FROM public.exercises x WHERE x.name = p.easier ORDER BY x.created_at LIMIT 1),
    harder_id  = (SELECT x.id FROM public.exercises x WHERE x.name = p.harder ORDER BY x.created_at LIMIT 1)
FROM public._ex_import_pullup p
WHERE e.name = p.name;

-- ── 7. Exercise swaps: "קל לי מדי" / "קשה לי מדי" in a workout, a bot suggestion
--       the coach approved, or a coach's change. Shown in the admin. ─────────
CREATE TABLE IF NOT EXISTS public.exercise_swaps (
  id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          UUID        NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  -- The row in his plan that changed (kept even if the row is later removed).
  plan_exercise_id UUID        REFERENCES public.workout_plan_exercises(id) ON DELETE SET NULL,
  from_exercise_id UUID        REFERENCES public.exercises(id) ON DELETE SET NULL,
  to_exercise_id   UUID        REFERENCES public.exercises(id) ON DELETE SET NULL,
  -- 'harder' = it was too easy; 'easier' = it was too hard.
  direction        TEXT        NOT NULL CHECK (direction IN ('easier', 'harder')),
  source           TEXT        NOT NULL DEFAULT 'app' CHECK (source IN ('app', 'bot', 'coach')),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS exercise_swaps_user_idx ON public.exercise_swaps (user_id, created_at DESC);

ALTER TABLE public.exercise_swaps ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Trainee reads own exercise swaps" ON public.exercise_swaps;
CREATE POLICY "Trainee reads own exercise swaps" ON public.exercise_swaps
  FOR SELECT USING (auth.uid() = user_id);
DROP POLICY IF EXISTS "Trainee records own exercise swaps" ON public.exercise_swaps;
CREATE POLICY "Trainee records own exercise swaps" ON public.exercise_swaps
  FOR INSERT WITH CHECK (auth.uid() = user_id AND source = 'app');
DROP POLICY IF EXISTS "Admins manage exercise swaps" ON public.exercise_swaps;
CREATE POLICY "Admins manage exercise swaps" ON public.exercise_swaps
  FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());

-- ── 8. Checks. Each of the first three should return no rows. ────────────────
-- 7a. An exercise of the file that isn't in the library after this (e.g. an existing one under yet another name).
SELECT 'missing' AS problem, s.name FROM public._ex_import_src s
WHERE NOT EXISTS (SELECT 1 FROM public.exercises x WHERE x.name = s.name);

-- 7b. An easier / harder name that didn't resolve to an exercise.
SELECT 'link' AS problem, s.name, s.easier, s.harder FROM public._ex_import_src s JOIN public.exercises e ON e.name = s.name
WHERE (s.easier IS NOT NULL AND e.easier_id IS NULL) OR (s.harder IS NOT NULL AND e.harder_id IS NULL);

-- 7c. A name that's in the library twice (the update touched both).
SELECT 'duplicate' AS problem, name, count(*) FROM public.exercises GROUP BY name HAVING count(*) > 1;

-- The work tables (only needed inside this run).
DROP TABLE public._ex_import_src;
DROP TABLE public._ex_import_pullup;

-- 7d. The totals: 184 with a level (180 + the 4 pull-up ones); left as they were: 2 ("Running").
SELECT count(*) FILTER (WHERE level IS NOT NULL) AS with_level,
       count(*) FILTER (WHERE level IS NULL)     AS left_as_is,
       count(*) FILTER (WHERE media_url IS NULL AND level IS NOT NULL) AS without_video
FROM public.exercises;

COMMIT;
